export function renderPerisaiPancasilaSvg(params: PerisaiPancasilaParams): string {
  const silaParam = String(params.sila || params.pointer || '1').toLowerCase();
  const labelChar = params.label || 'X';

  let targetSila = 1;
  if (silaParam === '1' || silaParam.includes('bintang') || silaParam.includes('ketuhanan')) targetSila = 1;
  else if (silaParam === '2' || silaParam.includes('rantai') || silaParam.includes('kemanusiaan')) targetSila = 2;
  else if (silaParam === '3' || silaParam.includes('beringin') || silaParam.includes('persatuan')) targetSila = 3;
  else if (silaParam === '4' || silaParam.includes('banteng') || silaParam.includes('kerakyatan')) targetSila = 4;
  else if (silaParam === '5' || silaParam.includes('padi') || silaParam.includes('kapas') || silaParam.includes('keadilan')) targetSila = 5;

  const targetCoords: Record<number, { x: number; y: number; bx: number; by: number }> = {
    1: { x: 564.8, y: 322, bx: 564.8, by: 262 },
    2: { x: 615, y: 380, bx: 675, by: 380 },
    3: { x: 615, y: 265, bx: 675, by: 265 },
    4: { x: 515, y: 265, bx: 455, by: 265 },
    5: { x: 515, y: 380, bx: 455, by: 380 }
  };

  const target = targetCoords[targetSila] || targetCoords[1];
  const safeLabel = escapeXml(labelChar);

  // Jika params.showAll = true, tidak ada panah fokus
  const pointerMarkup = params.showAll ? '' : `
    <g>
      <circle cx="${target.x}" cy="${target.y}" r="26" fill="none" stroke="#e11d48" stroke-width="2.5" stroke-dasharray="4,3"/>
      <line x1="${target.bx}" y1="${target.by}" x2="${target.x}" y2="${target.y}" stroke="#e11d48" stroke-width="2.5" marker-end="url(#arrOfficial)"/>
      <circle cx="${target.bx}" cy="${target.by}" r="12" fill="#e11d48" stroke="#ffffff" stroke-width="2"/>
      <text x="${target.bx}" y="${target.by + 4.5}" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">${safeLabel}</text>
    </g>
    <text x="564.8" y="460" text-anchor="middle" font-size="11" font-weight="600" fill="#475569">Perhatikan lambang yang ditunjuk oleh huruf "${safeLabel}"!</text>
  `;

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="430 185 270 285" width="380" height="390" style="background:#ffffff; font-family:'Segoe UI',Arial,sans-serif; border-radius:8px;">
  <defs>
    <marker id="arrOfficial" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
      <path d="M 0 1.5 L 10 5 L 0 8.5 z" fill="#e11d48" />
    </marker>
  </defs>

  <rect x="430" y="185" width="270" height="285" fill="#ffffff" rx="6"/>
  <text x="564.8" y="206" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">Perisai Garuda Pancasila</text>

  <!-- SHIELD RESMI GARUDA PANCASILA -->
  <g>
    ${OFFICIAL_SHIELD_XML}
  </g>

  ${pointerMarkup}
</svg>`;
}
